-- Stop if any affected published story or question differs from the reviewed 0.84 baseline.
-- Update paragraphs only. Preserve story/question IDs, quiz answers, flags, drafts, history and dictionary preferences.
CREATE TABLE _a1_085_guard(ok INTEGER NOT NULL CHECK(ok=1));
INSERT INTO _a1_085_guard SELECT CASE WHEN (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=20 AND title='Погода сьогодні' AND json(paragraphs_json)=json('["Сьогодні в нашому маленькому місті тепло, і люди гуляють біля річки. Небо синє. На небі немає хмар, і сонце світить над будинками. Біля парку жінка веде маленьку дівчинку до води. На дівчинці біла сорочка, а на жінці теплий светр. Вони повільно йдуть і говорять про школу.","У парку діти грають у м''яч на великій зеленій траві. Поруч стоїть старий велосипед, а біля нього лежить рюкзак. Спочатку хлопець грає з друзями, потім сідає біля річки. Він відпочиває. На воді світить сонце."]') AND show_word_count=1)=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=20))=5 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=20) AND display_order=1 AND prompt='Яке сьогодні небо?' AND correct_answer='Синє' AND json(wrong_answers_json)=json('["Сіре","Біле","Червоне"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=20) AND display_order=2 AND prompt='Кого веде жінка?' AND correct_answer='Дівчинку' AND json(wrong_answers_json)=json('["Хлопця","Бабусю","Друга"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=20) AND display_order=3 AND prompt='Що на жінці?' AND correct_answer='Теплий светр' AND json(wrong_answers_json)=json('["Біла сорочка","Синя шапка","Червона куртка"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=20) AND display_order=4 AND prompt='Що хлопець робить після гри?' AND correct_answer='Сідає біля річки' AND json(wrong_answers_json)=json('["Іде до магазину","Читає в школі","Шукає велосипед"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=20) AND display_order=5 AND prompt='Де світить сонце в кінці?' AND correct_answer='На воді' AND json(wrong_answers_json)=json('["На книжці","На столі","На ліжку"]'))=1 AND (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=21 AND title='Пори року' AND json(paragraphs_json)=json('["Біля нашого будинку росте велике дерево. Узимку на його гілках лежить білий сніг. Листя немає. Люди йдуть до магазину в теплих куртках і шапках. Навесні на дереві знову є маленьке зелене листя. Біля будинку вже тепло, і діти разом грають у м''яч.","Улітку листя велике, а під деревом стоїть лавка. Там сидить бабуся і читає книжку про море. Поруч її онук їсть морозиво і слухає тиху музику. Восени листя жовте і червоне, а на вулиці холодно. Діти йдуть до школи і несуть книжки в рюкзаках.","Дерево весь рік стоїть біля нашого будинку. Дерево поруч. Кожна пора року має свої кольори."]') AND show_word_count=1)=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=21))=5 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=21) AND display_order=1 AND prompt='Що на гілках узимку?' AND correct_answer='Білий сніг' AND json(wrong_answers_json)=json('["Жовте листя","Червоні квіти","Зелені яблука"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=21) AND display_order=2 AND prompt='Яке листя навесні?' AND correct_answer='Маленьке зелене' AND json(wrong_answers_json)=json('["Велике жовте","Маленьке червоне","Велике біле"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=21) AND display_order=3 AND prompt='Хто читає влітку?' AND correct_answer='Бабуся' AND json(wrong_answers_json)=json('["Онук","Дівчинка","Учитель"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=21) AND display_order=4 AND prompt='Куди діти йдуть восени?' AND correct_answer='До школи' AND json(wrong_answers_json)=json('["До моря","До річки","До парку"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=21) AND display_order=5 AND prompt='Де дерево взимку й улітку?' AND correct_answer='Біля будинку' AND json(wrong_answers_json)=json('["Біля школи","Біля річки","Біля магазину"]'))=1 AND (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=22 AND title='Мій одяг' AND json(paragraphs_json)=json('["Мій одяг лежить у великій шафі біля ліжка. Уранці я відкриваю двері шафи і вибираю речі для роботи. Тут є сині штани, біла сорочка і сірий светр. Я працюю в офісі біля парку. До роботи йду пішки.","Сьогодні холодно. На сорочку я одягаю теплий светр, а потім куртку. Беру ключі. Біля дверей стоїть моє взуття, а на полиці лежить шапка. Я дивлюся в дзеркало і поправляю светр.","Це мій улюблений светр із великими м''якими рукавами. Увечері я знову ношу його вдома. Сідаю на диван і беру книжку. Мої руки в теплих рукавах."]') AND show_word_count=1)=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=22))=5 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=22) AND display_order=1 AND prompt='Де лежить одяг?' AND correct_answer='У шафі' AND json(wrong_answers_json)=json('["На дивані","Під столом","У сумці"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=22) AND display_order=2 AND prompt='Де працює авторка?' AND correct_answer='В офісі' AND json(wrong_answers_json)=json('["У школі","У магазині","У парку"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=22) AND display_order=3 AND prompt='Що авторка одягає на сорочку?' AND correct_answer='Светр' AND json(wrong_answers_json)=json('["Шапку","Штани","Взуття"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=22) AND display_order=4 AND prompt='Що вона бере після куртки?' AND correct_answer='Ключі' AND json(wrong_answers_json)=json('["Книжку","Чашку","Телефон"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=22) AND display_order=5 AND prompt='Які рукави у светра?' AND correct_answer='Великі й м''які' AND json(wrong_answers_json)=json('["Малі й холодні","Нові й білі","Сині й короткі"]'))=1 AND (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=23 AND title='Кольори навколо мене' AND json(paragraphs_json)=json('["З вікна своєї кімнати я бачу синє небо і зелене дерево. Біля вікна стоїть мій стіл для роботи. На столі біла лампа, а поруч червоний зошит. Я беру зошит і пишу кілька слів про свій день. Потім дивлюся на жовті квіти біля книжок. Тут світло.","Увечері я сиджу на кухні, а сестра готує чай. Переді мною синя чашка, і біля неї синій олівець. Синій — мій улюблений колір. Спочатку я п''ю чай, потім малюю море. Уже тихо. На папері синє море."]') AND show_word_count=1)=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=23))=5 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=23) AND display_order=1 AND prompt='Що автор бачить із вікна?' AND correct_answer='Небо і дерево' AND json(wrong_answers_json)=json('["Море і човен","Магазин і школу","Річку і міст"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=23) AND display_order=2 AND prompt='Яка лампа на столі?' AND correct_answer='Біла' AND json(wrong_answers_json)=json('["Синя","Зелена","Жовта"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=23) AND display_order=3 AND prompt='Які квіти біля книжок?' AND correct_answer='Жовті' AND json(wrong_answers_json)=json('["Червоні","Білі","Сині"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=23) AND display_order=4 AND prompt='Який колір автор любить?' AND correct_answer='Синій' AND json(wrong_answers_json)=json('["Білий","Жовтий","Червоний"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=23) AND display_order=5 AND prompt='Що автор робить після чаю?' AND correct_answer='Малює море' AND json(wrong_answers_json)=json('["Пише в зошиті","Читає книжку","Готує вечерю"]'))=1 AND (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=24 AND title='Котра година?' AND json(paragraphs_json)=json('["О сьомій годині дзвонить будильник біля мого ліжка. Я встаю. На кухні висить великий годинник, і я часто дивлюся на нього. О восьмій я снідаю, а потім шукаю ключі від офісу. Уже пізно. Я майже запізнююся на роботу, тому швидко беру сумку.","Робота починається о дев''ятій, і я вже сиджу за столом. О першій годині обідаю з подругою біля роботи. Увечері вдома заряджаю телефон і читаю кілька сторінок. Потім я вимикаю лампу і ставлю будильник біля ліжка. О десятій я лягаю спати."]') AND show_word_count=1)=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=24))=5 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=24) AND display_order=1 AND prompt='Де висить годинник?' AND correct_answer='На кухні' AND json(wrong_answers_json)=json('["В офісі","У коридорі","Біля ліжка"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=24) AND display_order=2 AND prompt='Що авторка шукає після їжі?' AND correct_answer='Ключі від офісу' AND json(wrong_answers_json)=json('["Свою книжку","Новий телефон","Теплий светр"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=24) AND display_order=3 AND prompt='Коли починається робота?' AND correct_answer='О дев''ятій' AND json(wrong_answers_json)=json('["О сьомій","О восьмій","О першій"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=24) AND display_order=4 AND prompt='З ким авторка обідає?' AND correct_answer='З подругою' AND json(wrong_answers_json)=json('["З мамою","Із сестрою","З бабусею"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=24) AND display_order=5 AND prompt='Коли авторка лягає спати?' AND correct_answer='О десятій' AND json(wrong_answers_json)=json('["О першій","О сьомій","О дев''ятій"]'))=1 THEN 1 ELSE 0 END;
DROP TABLE _a1_085_guard;
UPDATE texts SET paragraphs_json='["Уранці сонце світить у вікна нашого маленького будинку. Сьогодні в місті тепло. З вікна будинку біля парку видно синє небо. Жінка повільно веде маленьку дівчинку до річки біля парку. На жінці теплий светр, а на дівчинці біла сорочка. Поруч хлопець повільно їде на велосипеді з великим рюкзаком.","Спочатку хлопець грає з друзями в м''яч біля річки. Жінка з дівчинкою сидить на лавці біля старого дерева. Після гри хлопець сідає біля річки і п''є воду. Велосипед стоїть поруч. Жінка з дівчинкою тепер дивиться на воду біля лавки. На воді світить сонце."]',updated_at=CURRENT_TIMESTAMP WHERE level='A1' AND display_order=20;
UPDATE texts SET paragraphs_json='["Біля нашого будинку стоїть велике дерево. Узимку на його гілках лежить білий сніг. На лавці тихо. Бабуся сидить удома з книжкою біля вікна. Навесні на дереві є маленьке зелене листя. Бабуся вже читає свою книжку на лавці біля дерева.","Улітку бабуся часто сидить на цій лавці з онуком. Вона читає книжку про море, а він їсть морозиво. Восени на дереві вже жовте і червоне листя. Біля лавки холодно. Бабуся також показує дітям червоне листя біля лавки. Діти з рюкзаками йдуть до школи біля нашого будинку.","Узимку бабуся знову читає вдома біля вікна. Вона бачить білий сніг на своєму дереві. Кожна пора року має свої кольори."]',updated_at=CURRENT_TIMESTAMP WHERE level='A1' AND display_order=21;
UPDATE texts SET paragraphs_json='["Мій одяг лежить у шафі біля ліжка. Уранці я вибираю одяг для роботи в нашому офісі. На полиці сині штани, біла сорочка і сірий светр. Я беру білу сорочку з полиці. Сірий светр теж кладу на ліжко біля сорочки.","Сьогодні холодно. На сорочку я одягаю мій улюблений сірий светр. У дзеркалі я бачу сорочку і сірий светр. Потім я одягаю куртку. Беру ключі біля дверей. До роботи я йду пішки через наш тихий парк.","Увечері я сиджу вдома на дивані з книжкою. Куртка в шафі. Мій светр має великі м''які рукави. Я п''ю теплий чай. Мої руки в теплих рукавах."]',updated_at=CURRENT_TIMESTAMP WHERE level='A1' AND display_order=22;
UPDATE texts SET paragraphs_json='["Я щодня працюю вдома біля великого вікна моєї кімнати. Із вікна я бачу синє небо і зелене дерево. На столі стоїть біла лампа біля червоного зошита. Я пишу в зошиті кілька слів про свій день. Сестра ставить квіти у воду біля моїх книжок. Квіти жовті.","Увечері сестра ставить на мій стіл синю чашку теплого чаю. Після роботи я повільно п''ю чай біля вікна. У моїй маленькій коробці біля книжок є синій олівець. Синій — мій улюблений колір. Я беру синій олівець і малюю море на білому папері. На папері синє море."]',updated_at=CURRENT_TIMESTAMP WHERE level='A1' AND display_order=23;
UPDATE texts SET paragraphs_json='["На кухні біля вікна висить наш великий годинник. О сьомій годині я снідаю за столом біля вікна. Після сніданку я шукаю ключі від офісу у своїй сумці. Де мої ключі? Уже пізно. Я майже запізнююся на роботу, а ключі лежать біля дверей.","О дев''ятій я вже сиджу за своїм столом в офісі. Моя робота починається о дев''ятій. Удень я обідаю з подругою в парку біля роботи. Увечері вдома я заряджаю телефон і читаю кілька сторінок своєї книжки. Потім ставлю будильник біля ліжка на сьому годину. О десятій я лягаю спати."]',updated_at=CURRENT_TIMESTAMP WHERE level='A1' AND display_order=24;
